package com.questcape.guide;

import com.google.gson.*;
import com.questcape.integration.BoundedHttp;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GuideRepositoryTest
{
	private JsonStore store;
	private BoundedHttp http;
	private GuideRepository repo;

	@Before
	public void setup() throws Exception
	{
		store = new JsonStore(new Gson(), Files.createTempDirectory("oqg-guide-test"));
		http = mock(BoundedHttp.class);
		repo = new GuideRepository(new GuideParser(), http, store);
	}

	private String payload(String html)
	{
		JsonObject parse = new JsonObject(), body = new JsonObject(), text = new JsonObject();
		text.addProperty("*", html);
		parse.add("text", text);
		parse.addProperty("revid", 123);
		body.add("parse", parse);
		return body.toString();
	}

	private BoundedHttp.Result result(int code, String body)
	{
		return new BoundedHttp.Result(code, body, "tag", "modified", null, null);
	}

	@Test
	public void offlineStartupAndAtomicLastGoodCache() throws Exception
	{
		when(http.get(anyString(), anyMap(), anyInt())).thenThrow(new IOException("Offline"));
		assertNull(repo.load());
		assertTrue(repo.isStale(System.currentTimeMillis()));
		try
		{
			repo.refresh(Runnable::run, 10000).join();
			fail();
		}
		catch (CompletionException expected)
		{
		}
		assertNull(repo.current());
		String original = GuideParserTest.fixture();
		doReturn(result(200, payload(original))).when(http).get(anyString(), anyMap(), anyInt());
		GuideSnapshot good = repo.refresh(Runnable::run, 20000).join();
		assertEquals(351, good.getRows().size());
		when(http.get(anyString(), anyMap(), anyInt()))
			.thenReturn(result(200, payload(GuideParserTest.table(GuideParserTest.activity("short")))));
		try
		{
			repo.refresh(Runnable::run, 30000).join();
			fail();
		}
		catch (CompletionException expected)
		{
		}
		assertSame(good, repo.current());
		GuideRepository restart = new GuideRepository(new GuideParser(), http, store);
		assertEquals(351, restart.load().getRows().size());
		assertTrue(restart.isStale(good.getValidatedAt() + GuideRepository.MAX_AGE));
	}

	@Test
	public void cachedGuideGetsCurrentClassificationsWithoutNetworkOrLosingManualKeys() throws Exception
	{
		GuideParser parser = new GuideParser();
		List<GuideRow> current = parser.parse(GuideParserTest.fixture());
		List<GuideRow> legacy = new ArrayList<>();
		for (GuideRow row : current)
		{
			boolean oldUnknown = row.getKind() == GuideRow.Kind.INFORMATION || row.getTargets().containsKey("COMBAT")
				|| row.getKind() == GuideRow.Kind.MINIQUEST && row.getQuestIdentity() == null;
			legacy.add(oldUnknown
				? new GuideRow("UNKNOWN:" + row.getPosition(), row.getPosition(), GuideRow.Kind.UNKNOWN, row.getTitle(),
					row.getWikiTarget(), null, Map.of(), row.getFields(), row.getLinks())
				: row);
		}
		store.write("guide", "standard", new GuideSnapshot("cached", 1000, 2000, "tag", "date", legacy));
		GuideSnapshot restored = repo.load();
		assertEquals(current, restored.getRows());
		assertEquals("tag", restored.getEtag());
		assertEquals(2000, restored.getValidatedAt());
		verifyNoInteractions(http);
	}

	@Test
	public void requestsCoalesceAndRevalidateConditionally() throws Exception
	{
		List<Runnable> queue = new ArrayList<>();
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(200, payload(GuideParserTest.fixture())));
		CompletableFuture<GuideSnapshot> first = repo.refresh(queue::add, 10000);
		assertSame(first, repo.refresh(queue::add, 11000));
		assertEquals(1, queue.size());
		queue.remove(0).run();
		first.join();
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(304, ""));
		repo.refresh(Runnable::run, 20000).join();
		verify(http).get(eq(GuideRepository.ENDPOINT),
			eq(Map.of("If-None-Match", "tag", "If-Modified-Since", "modified")), eq(4_000_000));
		assertTrue(repo.refresh(Runnable::run, 20001).isCompletedExceptionally());
	}

	@Test
	public void cancelDoesNotWaitForCacheWriteOrPublishCanceledRefresh() throws Exception
	{
		JsonStore slowStore = mock(JsonStore.class);
		GuideRepository slow = new GuideRepository(new GuideParser(), http, slowStore);
		CompletableFuture<Void> entered = new CompletableFuture<>(), release = new CompletableFuture<>();
		doAnswer(i ->
		{
			entered.complete(null);
			release.get(5, TimeUnit.SECONDS);
			return null;
		})
			.when(slowStore).write(anyString(), anyString(), any());
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(200, payload(GuideParserTest.fixture())));
		ExecutorService worker = Executors.newSingleThreadExecutor();
		try
		{
			CompletableFuture<GuideSnapshot> refresh = slow.refresh(worker, 10000);
			entered.get(5, TimeUnit.SECONDS);
			CompletableFuture.runAsync(slow::cancel).get(1, TimeUnit.SECONDS);
			release.complete(null);
			worker.submit(() ->
			{
			}).get(5, TimeUnit.SECONDS);
			assertTrue(refresh.isCancelled());
			assertNull(slow.current());
		}
		finally
		{
			release.complete(null);
			worker.shutdownNow();
		}
	}

	@Test
	public void revisedContentAndCanceledWork() throws Exception
	{
		String original = GuideParserTest.fixture();
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(200, payload(original)));
		GuideSnapshot old = repo.refresh(Runnable::run, 10000).join();
		String added = original.replace("</table>", GuideParserTest.activity("New route activity") + "</table>");
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(200, payload(added)));
		assertEquals(old.getRows().size() + 1, repo.refresh(Runnable::run, 20000).join().getRows().size());
		List<Runnable> queue = new ArrayList<>();
		repo.refresh(queue::add, 30000);
		repo.cancel();
		queue.get(0).run();
		assertEquals(352, repo.current().getRows().size());
	}
}

package com.questcape.guide;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GuideParserTest
{
	public static String fixture() throws Exception
	{
		try (java.io.InputStream in = GuideParserTest.class.getResourceAsStream("/fixtures/wiki-guide-15336101.html"))
		{
			return new String(Objects.requireNonNull(in).readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	@Test
	public void capturedWikiRetainsEveryRowAndAllFields() throws Exception
	{
		String source = fixture();
		List<GuideRow> rows = new GuideParser().parse(source);
		assertEquals(source.split("<tr[ >]", -1).length - 2, rows.size());
		assertEquals("Learning the Ropes", rows.get(0).getTitle());
		assertTrue(rows.stream().anyMatch(r -> r.getTitle().startsWith("Hand in") && r.isManual()));
		assertTrue(rows.stream()
			.anyMatch(r -> r.getKind() == GuideRow.Kind.TRAINING && r.getTargets().containsKey("FIREMAKING")));
		assertTrue(rows.stream().allMatch(r -> r.getFields().size() == 7));
		System.out.println("Captured guide: " + rows.size() + " rows; kinds " + rows.stream().collect(
			java.util.stream.Collectors.groupingBy(GuideRow::getKind, java.util.stream.Collectors.counting())));
	}

	public static String table(String rows)
	{
		return "<table><caption>Old School RuneScape Quest Guide</caption><tr><th>Quest/Activity</th><th>Quick Guide</th><th>New levels after quest</th><th>Quest points</th><th>Total QP</th><th>Additional info</th><th>Location</th></tr>"
			+ rows + "</table>";
	}

	public static String activity(String text)
	{
		return "<tr><th colspan='7'>" + text + "</th></tr>";
	}

	@Test
	public void stagesUnknownRowsAndCompoundTargetsSurviveReordering() throws Exception
	{
		String start = activity("Start miniquest: <a href='/w/In_Search_of_Knowledge'>In Search of Knowledge</a>");
		String end = activity("<a href='/w/In_Search_of_Knowledge'>In Search of Knowledge</a> (miniquest)");
		String training = activity("Train Attack and Strength from level 10 to level 20");
		String unknown = activity("Visit the brand new celestial gate");
		GuideParser parser = new GuideParser();
		List<GuideRow> rows = parser.parse(table(start + training + unknown + end));
		assertNotEquals(rows.get(0).getKey(), rows.get(3).getKey());
		assertEquals(Map.of("ATTACK", 20, "STRENGTH", 20), rows.get(1).getTargets());
		assertEquals(GuideRow.Kind.UNKNOWN, rows.get(2).getKind());
		List<GuideRow> reordered = parser.parse(table(end + unknown + start + training));
		assertEquals(rows.get(0).getKey(), reordered.get(2).getKey());
		List<GuideRow> duplicates = parser.parse(table(activity("Unlock: gate") + activity("Unlock: gate")));
		assertEquals(2, duplicates.size());
		assertNotEquals(duplicates.get(0).getKey(), duplicates.get(1).getKey());
		assertFalse("Indistinguishable checks must not transfer", duplicates.get(0).isManual());
	}

	@Test
	public void rowspansAndUnsafeMarkup() throws Exception
	{
		String row = "<tr><td rowspan='2'>Unlock: boat</td><td>N/A</td><td>1</td><td>0</td><td>1</td><td><script>alert(1)</script><a href='javascript:alert(2)'>unsafe</a>Notes</td><td>Port</td></tr>";
		String second = "<tr><td>N/A</td><td>2</td><td>0</td><td>2</td><td>Second visit</td><td>Port</td></tr>";
		List<GuideRow> rows = new GuideParser().parse(table(row + second));
		assertEquals(2, rows.size());
		assertFalse(rows.get(0).getFields().toString().contains("alert(1)"));
		assertTrue(rows.get(0).getLinks().isEmpty());
		assertNull(GuideParser.safeWikiLink("https://oldschool.runescape.wiki.evil.test/w/X"));
	}

	@Test
	public void currentGuideClassifiesEveryStepAndKeepsNotesOutsideTheStepCount() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(fixture());
		for (String title : Arrays.asList("Natural history quiz", "Knight Waves Training Grounds"))
		{
			GuideRow miniquest = rows.stream().filter(row -> row.getTitle().startsWith(title)).findFirst().orElseThrow();
			assertEquals(GuideRow.Kind.MINIQUEST, miniquest.getKind());
			assertTrue("Unmapped miniquests can be completed manually", miniquest.isManual());
		}
		GuideRow combat = rows.stream().filter(row -> row.getTitle().startsWith("Train Combat")).findFirst().orElseThrow();
		assertEquals(GuideRow.Kind.TRAINING, combat.getKind());
		assertEquals(Map.of("COMBAT", 85), combat.getTargets());
		assertEquals(2, rows.stream().filter(row -> row.getKind() == GuideRow.Kind.INFORMATION).count());
		assertEquals(349, rows.stream().filter(GuideRow::isActionable).count());
		assertTrue(rows.stream().noneMatch(row -> row.getKind() == GuideRow.Kind.UNKNOWN));
		assertEquals(GuideRow.Kind.INFORMATION, rows.get(rows.size() - 1).getKind());
	}

	@Test
	public void trainingVariantsKeepOptionalRecommendationsSeparateAndUnresolvedTargetsUnknown() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(table(
			activity("Train Combat level to 91 (Recommended: also train Slayer)")
				+ activity("Train Attack to level 40 (Recommended: train Defence to level 60)")
				+ activity("Train Strength to 50")
				+ activity("Train Necromancy and Attack to level 20")
				+ activity("Train Slayer until ready")
				+ activity("Train Magic to level 9999999999999999999999")));
		assertTrue(rows.stream().allMatch(row -> row.getKind() == GuideRow.Kind.TRAINING));
		assertEquals(Map.of("COMBAT", 91), rows.get(0).getTargets());
		assertEquals(Map.of("ATTACK", 40), rows.get(1).getTargets());
		assertEquals(Map.of("STRENGTH", 50), rows.get(2).getTargets());
		assertTrue(rows.subList(3, 6).stream().allMatch(row -> row.getTargets().isEmpty()));
	}

	@Test
	public void commentsUseLayoutAndLanguageRatherThanSpecificTitlesOrPositions() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(table(
			activity("Congratulations on reaching this milestone!")
				+ activity("All remaining rewards can be collected in any order")
				+ activity("Note: <a href='/w/Cooks_Assistant'>Cook's Assistant</a> has optional dialogue.")
				+ activity("A completely different cape!")
				+ activity("Visit the newly discovered gate!")
				+ activity("Mystery activity")
				+ "<tr><td>Unmapped destination!</td><td>N/A</td><td>1</td><td>0</td><td>1</td><td></td><td>Port</td></tr>"));
		assertTrue(rows.subList(0, 4).stream().noneMatch(GuideRow::isActionable));
		assertTrue(rows.subList(4, 7).stream().allMatch(row -> row.getKind() == GuideRow.Kind.UNKNOWN));
	}

	@Test(timeout = 2000)
	public void malformedTrainingCannotCauseExponentialBacktracking() throws Exception
	{
		GuideRow malformed = GuideClassifier.classify(0, "Train ba," + "aand".repeat(20000), "",
			Map.of(), Map.of(), true);
		assertEquals(GuideRow.Kind.TRAINING, malformed.getKind());
		assertTrue(malformed.getTargets().isEmpty());
		List<GuideRow> rows = new GuideParser().parse(table(
			activity("Train Attack, Strength and Defence to level 40")
				+ activity("Train Magic &amp; Ranged from level 10 to level 50")
				+ activity("Train Attack to 40 and Strength to 50")));
		assertEquals(Map.of("ATTACK", 40, "STRENGTH", 40, "DEFENCE", 40), rows.get(0).getTargets());
		assertEquals(Map.of("MAGIC", 50, "RANGED", 50), rows.get(1).getTargets());
		assertEquals(Map.of("ATTACK", 40, "STRENGTH", 50), rows.get(2).getTargets());
	}

	@Test
	public void normalizedReorderedHeadersPreserveTitleAndValidatedWikiTarget() throws Exception
	{
		String row = "<tr><td>Quick guide</td><td><a href='javascript:alert(1)'>Unsafe</a> "
			+ "<a href='/w/Cook%27s_Assistant'>Cook's Assistant</a></td><td>1</td><td>1</td>"
			+ "<td>1</td><td>Notes</td><td>Lumbridge</td></tr>";
		String source = table(row).replace("<th>Quest/Activity</th><th>Quick Guide</th>",
			"<th>Quick Guide</th><th> quest/activity </th>");
		GuideRow parsed = new GuideParser().parse(source).get(0);
		assertEquals("Unsafe Cook's Assistant", parsed.getTitle());
		assertEquals("Cook's Assistant", parsed.getWikiTarget());
		assertEquals("COOKS_ASSISTANT", parsed.getQuestIdentity());
		assertEquals(7, parsed.getFields().size());
		assertEquals(1, parsed.getLinks().size());
	}

	@Test
	public void missingAmbiguousOrMalformedTablesFail() throws Exception
	{
		String valid = table(activity("Unknown new row"));
		for (String input : Arrays.asList("<p>No table</p>", valid + valid, valid.replace("colspan='7'", "colspan='2'"),
			valid.replace("Quest points", "Changed header")))
		{
			try
			{
				new GuideParser().parse(input);
				fail("Expected invalid table to fail");
			}
			catch (java.io.IOException expected)
			{
			}
		}
	}
}

package com.questcape.progress;

import com.google.gson.Gson;
import com.questcape.guide.*;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import net.runelite.api.*;
import net.runelite.client.config.*;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ProgressTest
{
	public static AccountProgress observation(String scope, String name, String mode,
		Map<String, AccountProgress.QuestStatus> quests, Map<String, Integer> levels)
	{
		return new AccountProgress(scope, name, mode, "Live RuneLite", System.currentTimeMillis(),
			System.currentTimeMillis(), quests, levels, Map.of(), Set.of());
	}

	@Test
	public void combatTrainingUsesRealSkillSnapshotAndUnmappedMiniquestsUseManualChecks() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(GuideParserTest.table(
			GuideParserTest.activity("Train Combat level to 85 (Recommended: also train Slayer)")
				+ GuideParserTest.activity("Natural history quiz (miniquest)")
				+ GuideParserTest.activity("Train an unknown skill")));
		Map<String, Integer> levels = new HashMap<>();
		for (String skill : Arrays.asList("ATTACK", "STRENGTH", "DEFENCE", "HITPOINTS", "MAGIC", "RANGED", "PRAYER"))
		{
			levels.put(skill, 60);
		}
		AccountProgress lower = observation("live:A:STANDARD", "Player", "STANDARD", Map.of(), levels);
		assertEquals(Completion.State.INCOMPLETE, Completion.of(rows.get(0), lower).getState());
		levels.replaceAll((skill, level) -> 70);
		AccountProgress higher = observation("live:A:STANDARD", "Player", "STANDARD", Map.of(), levels);
		assertEquals(Completion.State.COMPLETE, Completion.of(rows.get(0), higher).getState());
		levels.remove("PRAYER");
		AccountProgress incomplete = observation("live:A:STANDARD", "Player", "STANDARD", Map.of(), levels);
		assertEquals(Completion.State.UNKNOWN, Completion.of(rows.get(0), incomplete).getState());
		assertEquals(Completion.State.UNKNOWN, Completion.of(rows.get(2), higher).getState());
		assertTrue(Completion.of(rows.get(1), higher).isManual());
		assertEquals(Completion.State.COMPLETE,
			Completion.of(rows.get(1), higher.withManual(Set.of(rows.get(1).getKey()))).getState());
	}

	@Test
	public void thresholdQuestStageAndManualSemantics() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(GuideParserTest.table(
			GuideParserTest.activity("Train Firemaking from level 34 to level 40")
				+ GuideParserTest.activity("Train Firemaking from level 40 to level 49")
				+ GuideParserTest.activity("Hand in Herbi Flax diary, from level 25 to level 25")
				+ GuideParserTest.activity("Unlock: balloon route")
				+ GuideParserTest
					.activity("Start miniquest: <a href='/w/In_Search_of_Knowledge'>In Search of Knowledge</a>")
				+ GuideParserTest
					.activity("<a href='/w/In_Search_of_Knowledge'>In Search of Knowledge</a> (miniquest)")));
		AccountProgress account = observation("live:A", "Alice", "STANDARD",
			Map.of("IN_SEARCH_OF_KNOWLEDGE", AccountProgress.QuestStatus.IN_PROGRESS),
			Map.of("FIREMAKING", 40, "HERBLORE", 99));
		assertEquals(Completion.State.COMPLETE, Completion.of(rows.get(0), account).getState());
