package com.questcape.guide;

import java.io.*;
import java.util.*;
import javax.swing.text.*;
import javax.swing.text.html.*;
import javax.swing.text.html.parser.ParserDelegator;

/** Inert DOM built with the JDK parser; no browser, remote image loads or extra Hub dependency. */
final class HtmlTree
{
	static final class Node
	{
		final String tag;
		final Map<String, String> attrs = new HashMap<>();
		final List<Object> content = new ArrayList<>();
		Node parent;

		Node(String tag)
		{
			this.tag = tag;
		}

		String attr(String key)
		{
			return attrs.getOrDefault(key, "");
		}

		List<Node> children(String tag)
		{
			List<Node> result = new ArrayList<>();
			for (Object item : content)
			{
				if (item instanceof Node && ((Node)item).tag.equals(tag))
				{
					result.add((Node)item);
				}
			}
			return result;
		}

		List<Node> all(String tag)
		{
			List<Node> result = new ArrayList<>();
			for (Object item : content)
			{
				if (item instanceof Node)
				{
					Node node = (Node)item;
					if (node.tag.equals(tag))
					{
						result.add(node);
					}
					result.addAll(node.all(tag));
				}
			}
			return result;
		}

		String text()
		{
			if (Arrays.asList("script", "style", "iframe", "object").contains(tag))
			{
				return "";
			}
			StringBuilder out = new StringBuilder();
			for (Object part : content)
			{
				out.append(part instanceof Node ? ((Node)part).text() : part).append(' ');
			}
			return out.toString().replace('\u00a0', ' ').trim().replaceAll("\\s+", " ");
		}
	}

	static Node parse(String html) throws IOException
	{
		Node root = new Node("root");
		new ParserDelegator().parse(new StringReader(html), new HTMLEditorKit.ParserCallback()
		{
			Node current = root;

			Node add(HTML.Tag tag, MutableAttributeSet attrs)
			{
				Node node = new Node(tag.toString());
				Enumeration<?> names = attrs.getAttributeNames();
				while (names.hasMoreElements())
				{
					Object name = names.nextElement();
					node.attrs.put(name.toString(), String.valueOf(attrs.getAttribute(name)));
				}
				node.parent = current;
				current.content.add(node);
				return node;
			}

			@Override
			public void handleStartTag(HTML.Tag t, MutableAttributeSet a, int p)
			{
				current = add(t, a);
			}

			@Override
			public void handleSimpleTag(HTML.Tag t, MutableAttributeSet a, int p)
			{
				add(t, a);
			}

			@Override
			public void handleEndTag(HTML.Tag t, int p)
			{
				for (Node n = current; n != root; n = n.parent)
				{
					if (n.tag.equals(t.toString()))
					{
						current = n.parent;
						break;
					}
				}
			}

			@Override
			public void handleText(char[] data, int p)
			{
				current.content.add(new String(data));
			}
		}, true);
		return root;
	}
}

package com.questcape.guide;

import com.questcape.progress.Identities;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import javax.inject.Inject;

public class GuideParser
{
	private static final String CAPTION = "old school runescape quest guide";
	private static final List<String> HEADERS = Arrays.asList("Quest/Activity", "Quick Guide", "New levels after quest",
		"Quest points", "Total QP", "Additional info", "Location");

	@Inject
	public GuideParser()
	{
	}

	public List<GuideRow> parse(String html) throws IOException
	{
		if (html == null || html.length() > 4_000_000)
		{
			throw new IOException("Guide response exceeds limits");
		}
		HtmlTree.Node document = HtmlTree.parse(html);
		List<HtmlTree.Node> candidates = new ArrayList<>();
		for (HtmlTree.Node table : document.all("table"))
		{
			if (table.children("caption").stream().anyMatch(c -> Identities.normalize(c.text()).equals(CAPTION)))
			{
				candidates.add(table);
			}
		}
		if (candidates.size() != 1)
		{
			throw new IOException("Expected one captioned guide table; found " + candidates.size());
		}
		List<HtmlTree.Node> physical = candidates.get(0).all("tr");
		if (physical.size() < 2 || physical.size() > 2000)
		{
			throw new IOException("Guide table is empty or oversized");
		}
		Map<Integer, Span> spans = new HashMap<>();
		List<GuideRow> rows = new ArrayList<>();
		List<String> headers = null;
		for (HtmlTree.Node tr : physical)
		{
			List<HtmlTree.Node> cells = new ArrayList<>();
			for (Object child : tr.content)
			{
				if (child instanceof HtmlTree.Node)
				{
					HtmlTree.Node node = (HtmlTree.Node)child;
					if (node.tag.equals("td") || node.tag.equals("th"))
					{
						cells.add(node);
					}
				}
			}
			if (cells.isEmpty())
			{
				continue;
			}
			HtmlTree.Node[] grid = new HtmlTree.Node[7];
			for (Iterator<Map.Entry<Integer, Span>> it = spans.entrySet().iterator(); it.hasNext();)
			{
				Map.Entry<Integer, Span> entry = it.next();
				grid[entry.getKey()] = entry.getValue().node;
				if (--entry.getValue().remaining == 0)
				{
					it.remove();
				}
			}
			int column = 0;
			for (HtmlTree.Node cell : cells)
			{
				while (column < 7 && grid[column] != null)
				{
					column++;
				}
				int colspan = span(cell, "colspan"), rowspan = span(cell, "rowspan");
				if (column + colspan > 7)
				{
					throw new IOException("Unexpected guide column count");
				}
				for (int j = 0; j < colspan; j++)
				{
					if (grid[column] != null)
					{
						throw new IOException("Overlapping merged cells");
					}
					grid[column] = cell;
					if (rowspan > 1)
					{
						spans.put(column, new Span(cell, rowspan - 1));
					}
					column++;
				}
			}
			if (Arrays.stream(grid).anyMatch(Objects::isNull))
			{
				throw new IOException("Incomplete guide row");
			}
			if (headers == null)
			{
				headers = new ArrayList<>();
				for (HtmlTree.Node cell : grid)
				{
					headers.add(cell.text());
				}
				for (String header : HEADERS)
				{
					if (headers.stream().noneMatch(h -> Identities.normalize(h).equals(Identities.normalize(header))))
					{
						throw new IOException("Guide headers changed: " + headers);
					}
				}
				continue;
			}
			Map<String, String> fields = new LinkedHashMap<>(), links = new LinkedHashMap<>();
			for (int j = 0; j < 7; j++)
			{
				fields.put(headers.get(j), grid[j].text());
			}
			for (HtmlTree.Node anchor : tr.all("a"))
			{
				String href = safeWikiLink(anchor.attr("href"));
				if (href != null && !anchor.text().isEmpty())
				{
					links.put(href, anchor.text());
				}
			}
			HtmlTree.Node titleCell = grid[headers.indexOf(
				headers.stream().filter(h -> Identities.normalize(h).equals("quest/activity")).findFirst().get())];
			String title = titleCell.text();
			if (title.isBlank())
			{
				throw new IOException("Empty guide action");
			}
			String wikiTarget = "";
			for (HtmlTree.Node a : titleCell.all("a"))
			{
				String href = safeWikiLink(a.attr("href"));
				if (href != null && !a.text().isBlank())
				{
					wikiTarget = wikiTitle(href);
					break;
				}
			}
			boolean fullWidth = Arrays.stream(grid).allMatch(cell -> cell == titleCell);
			rows.add(GuideClassifier.classify(rows.size(), title, wikiTarget, fields, links, fullWidth));
		}
		if (!spans.isEmpty() || rows.isEmpty())
		{
			throw new IOException("Truncated guide table");
		}
		return distinguishRepeatedRows(rows);
	}

	/** Upgrade cached classifications offline; the stored field layout identifies full-width rows. */
	public GuideSnapshot reclassify(GuideSnapshot snapshot)
	{
		List<GuideRow> rows = new ArrayList<>();
		for (GuideRow row : snapshot.getRows())
		{
			boolean fullWidth = row.getFields().values().stream().allMatch(row.getTitle()::equals);
			rows.add(GuideClassifier.classify(row.getPosition(), row.getTitle(), row.getWikiTarget(),
				row.getFields(), row.getLinks(), fullWidth));
		}
		return new GuideSnapshot(snapshot.getRevision(), snapshot.getRetrievedAt(), snapshot.getValidatedAt(),
			snapshot.getEtag(), snapshot.getLastModified(), distinguishRepeatedRows(rows));
	}

	private static List<GuideRow> distinguishRepeatedRows(List<GuideRow> rows)
	{
		// Keep even identical repetitions visible, but never share a manual check between indistinguishable actions.
		Map<String, Long> counts = rows.stream()
			.collect(java.util.stream.Collectors.groupingBy(GuideRow::getKey, java.util.stream.Collectors.counting()));
		Map<String, Integer> occurrences = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			GuideRow row = rows.get(i);
			if (counts.get(row.getKey()) > 1)
			{
				String key = row.getKey() + ":repeated:" + occurrences.merge(row.getKey(), 1, Integer::sum);
				rows.set(i, new GuideRow(key, i, row.getKind(), row.getTitle(), row.getWikiTarget(),
					row.getQuestIdentity(), row.getTargets(), row.getFields(), row.getLinks()));
			}
		}
		return rows;
	}

	private static int span(HtmlTree.Node node, String name) throws IOException
	{
		if (node.attr(name).isEmpty())
		{
			return 1;
		}
		try
		{
			int value = Integer.parseInt(node.attr(name));
			if (value < 1 || value > 100)
			{
				throw new NumberFormatException();
			}
			return value;
		}
		catch (NumberFormatException e)
		{
			throw new IOException("Invalid merged cell", e);
		}
	}

	private static final class Span
	{
		final HtmlTree.Node node;
		int remaining;

		Span(HtmlTree.Node node, int remaining)
		{
			this.node = node;
			this.remaining = remaining;
		}
	}

	public static String safeWikiLink(String href)
	{
		try
		{
			URI uri = URI.create(GuideSnapshot.SOURCE).resolve(href);
			if (!"https".equalsIgnoreCase(uri.getScheme())
				|| !"oldschool.runescape.wiki".equalsIgnoreCase(uri.getHost())
				|| uri.getUserInfo() != null || (uri.getPort() != -1 && uri.getPort() != 443))
			{
				return null;
			}
			return uri.toASCIIString();
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String wikiTitle(String validatedUrl)
	{
		return URI.create(validatedUrl).getPath().replaceFirst("^/w/", "").replace('_', ' ');
	}

	public static String digest(String value)
	{
		try
		{
			byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder out = new StringBuilder();
			for (byte b : bytes)
			{
				out.append(String.format("%02x", b));
			}
			return out.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.questcape;

import com.questcape.guide.*;
import com.questcape.integration.*;
import com.questcape.progress.*;
import com.questcape.ui.GuidePanel;
import java.io.*;
import java.util.Map;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.*;

@PluginDescriptor(name = "QuestCape", description = "The ordered OSRS Wiki route with local character progress", tags =
{ "quest", "questcape", "guide", "wiki" })
public class QuestCapePlugin extends Plugin implements GuidePanel.Actions
{
	@Inject
	private ClientThread clientThread;
	@Inject
	private Client client;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private GuideRepository guide;
	@Inject
	private ProgressService progress;
	@Inject
	private LiveProgressReader liveReader;
	@Inject
	private TrainingGuideResolver training;
	@Inject
	private BoundedHttp http;
	@Inject
	private BrowserLinks browser;
	@Inject
	private SpriteManager spriteManager;
	private ThreadPoolExecutor worker, network;
	private GuidePanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	private final AtomicLong generation = new AtomicLong();
	private final AtomicLong liveGeneration = new AtomicLong();
	private volatile String contentStatus = "", progressStatus = "";
	private volatile boolean dirty = true, ready;
	private final AtomicBoolean livePending = new AtomicBoolean();
	private final AtomicBoolean renderQueued = new AtomicBoolean();

	private static ThreadPoolExecutor executor(String name, int threads)
	{
		return new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(16), r ->
		{
			Thread t = new Thread(r, name);
			t.setDaemon(true);
			return t;
		}, new ThreadPoolExecutor.AbortPolicy());
	}

	@Override
	protected void startUp() throws Exception
	{
		running = true;
		long token = generation.incrementAndGet();
		ready = false;
		dirty = true;
		progressStatus = "";
		worker = executor("questcape-state", 1);
		network = executor("questcape-http", 2);
		java.awt.image.BufferedImage icon;
		try (InputStream stream = getClass().getResourceAsStream("/quest-route-icon.png"))
		{
			if (stream == null)
			{
				throw new IOException("Missing navigation icon");
			}
			icon = ImageIO.read(stream);
		}
		final java.awt.image.BufferedImage loadedIcon = icon;
		SwingUtilities.invokeLater(() ->
		{
			if (!valid(token))
			{
				return;
			}
			panel = new GuidePanel(this, training);
			navigation = NavigationButton.builder().tooltip("QuestCape").icon(loadedIcon).priority(6).panel(panel)
				.build();
			toolbar.addNavigation(navigation);
			loadStepIcons(token);
			render();
		});
		work(() ->
		{
			try
			{
				guide.load();
				contentStatus = "Cached guide loaded.";
			}
			catch (IOException e)
			{
				contentStatus = e.getMessage();
			}
			render();
			if (guide.isStale(System.currentTimeMillis()))
			{
				refresh();
			}
		});
	}

	private void loadStepIcons(long token)
	{
		Map<GuideRow.Kind, Integer> sprites = Map.of(
			GuideRow.Kind.QUEST, SpriteID.AchievementDiaryIcons.BLUE_QUESTS,
			GuideRow.Kind.DIARY, SpriteID.AchievementDiaryIcons.GREEN_ACHIEVEMENT_DIARIES,
			GuideRow.Kind.TRAINING, SpriteID.SideIcons.STATS);
		sprites.forEach((kind, sprite) -> spriteManager.getSpriteAsync(sprite, 0, image ->
		{
			SwingUtilities.invokeLater(() ->
			{
				if (valid(token) && panel != null)
				{
					panel.setStepSprite(kind, image);
				}
			});
		}));
	}

	@Override
	protected void shutDown()
	{
		running = false;
		generation.incrementAndGet();
		liveGeneration.incrementAndGet();
		guide.cancel();
		http.cancel();
		if (worker != null)
		{
			worker.shutdownNow();
		}
		if (network != null)
		{
			network.shutdownNow();
		}
		progress.logout();
		livePending.set(false);
		NavigationButton old = navigation;
		SwingUtilities.invokeLater(() ->
		{
			if (old != null)
			{
				toolbar.removeNavigation(old);
			}
		});
		navigation = null;
		panel = null;
	}

	private boolean valid(long token)
	{
		return running && generation.get() == token;
	}

	private boolean work(Runnable action)
	{
		long token = generation.get();
		if (!running)
		{
			return false;
		}
		try
		{
			worker.execute(() ->
			{
				if (valid(token))
				{
					action.run();
				}
			});
			return true;
		}
		catch (RejectedExecutionException e)
		{
			show("Work queue is busy. Retry shortly.");
			return false;
		}
	}

	private void show(String value)
	{
		long token = generation.get();
		SwingUtilities.invokeLater(() ->
		{
			if (valid(token) && panel != null)
			{
				panel.message(value);
			}
		});
	}

	private void render()
	{
		if (!running || !renderQueued.compareAndSet(false, true))
		{
			return;
		}
		long token = generation.get();
		SwingUtilities.invokeLater(() ->
		{
			renderQueued.set(false);
			if (!valid(token) || panel == null)
			{
				return;
			}
			AccountProgress account = progress.current();
			panel.render(guide.current(), account, contentStatus, progressStatus, ready);
		});
	}

	@Override
	public void refresh()
	{
		if (!running)
		{
			return;
		}
		long token = generation.get();
		contentStatus = "Checking wiki…";
		render();
		try
		{
			guide.refresh(network, System.currentTimeMillis()).whenComplete((snapshot, failure) ->
			{
				if (!valid(token))
				{
					return;
				}
				contentStatus = failure == null ? "Guide is up to date." : "Refresh failed: " + cause(failure);
				render();
			});
		}
		catch (RejectedExecutionException e)
		{
			contentStatus = "Request queue is busy. Retry shortly.";
			render();
		}
	}

	@Override
	public void syncPlayer()
	{
		if (!running)
		{
			return;
		}
		long life = generation.get(), accountToken = liveGeneration.get();
		AccountProgress expected = progress.current();
		clientThread.invokeLater(() ->
		{
			if (!valid(life) || accountToken != liveGeneration.get())
			{
				return;
			}
			if (!ready || expected == null || client.getGameState() != GameState.LOGGED_IN)
			{
				show("Log in and wait for your character to be ready before syncing.");
				return;
			}
			captureProgress(true, expected.getScope());
		});
	}

	@Override
	public void manual(String scope, GuideRow row, boolean checked)
	{
		work(() ->
		{
			try
			{
				progress.toggleManual(scope, row, checked);
			}
			catch (IOException e)
			{
				show(e.getMessage());
			}
			render();
		});
	}

	@Override
	public void training(String skill)
	{
		String url = training.resolve(skill);
		long token = generation.get();
		show("Checking Theoatrix destination…");
		try
		{
			network.execute(() ->
			{
				try
				{
					String verified = training.verifyDestination(url);
					SwingUtilities.invokeLater(() ->
					{
						if (valid(token))
						{
							show(browser.open(verified));
						}
					});
				}
				catch (IOException | RuntimeException e)
				{
					if (valid(token))
					{
						show(e.getMessage() + " Link: " + url
							+ " · Click the training action to retry. Browse Theoatrix guides: "
							+ TrainingGuideResolver.FALLBACK);
					}
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			show("Request queue is busy. Retry shortly.");
		}
	}

	@Override
	public void source(String url)
	{
		if (GuideParser.safeWikiLink(url) != null || "https://creativecommons.org/licenses/by-nc-sa/3.0/".equals(url))
		{
			show(browser.open(url));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		dirty = true;
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			ready = false;
			liveGeneration.incrementAndGet();
			progress.logout();
			progressStatus = "";
			show("");
			render();
		}
		if (state == GameState.LOGGED_IN)
		{
			ready = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ready = true;
		if (!dirty)
		{
			return;
		}
		captureProgress(false, null);
	}

	/** Called on ClientThread. Only the immutable observation crosses to the disk worker. */
	private void captureProgress(boolean explicit, String expectedScope)
	{
		if (!livePending.compareAndSet(false, true))
		{
			if (explicit)
			{
				show("A character sync is already running. Retry shortly.");
			}
			return;
		}
		dirty = false;
		long life = generation.get(), accountToken = liveGeneration.get(), session = progress.token();
		try
		{
			AccountProgress observation = liveReader.read();
			if (observation == null || (expectedScope != null && !expectedScope.equals(observation.getScope())))
			{
				dirty = true;
				livePending.set(false);
				if (explicit)
				{
					show("Character changed or is not ready. Wait for the next game tick and retry.");
				}
				return;
			}
			if (explicit)
			{
				progressStatus = "Syncing character…";
				render();
			}
			if (!work(() ->
			{
				try
				{
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					AccountProgress previous = progress.current();
					boolean newAccount = previous == null || !previous.getScope().equals(observation.getScope());
					if (!progress.acceptLive(observation, session, explicit))
					{
						return;
					}
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					if (newAccount)
					{
						show("");
					}
					if (explicit || newAccount)
					{
						progressStatus = "Character synced locally";
					}
					render();
				}
				catch (IOException e)
				{
					if (valid(life) && accountToken == liveGeneration.get())
					{
						dirty = true;
						progressStatus = "Could not save character progress";
						show(e.getMessage());
						render();
					}
				}
				finally
				{
					if (valid(life))
					{
						livePending.set(false);
					}
				}
			}))
			{
				dirty = true;
				livePending.set(false);
			}
		}
		catch (RuntimeException e)
		{
			dirty = true;
			livePending.set(false);
			show("Character progress is not ready yet. Retry after the next game tick.");
		}
	}

	private static String cause(Throwable failure)
	{
		while (failure.getCause() != null)
		{
			failure = failure.getCause();
		}
		return failure.getMessage();
	}
}

package com.questcape.progress;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.config.*;

@Singleton
public class LiveProgressReader
{
	private final Client client;
	private final ConfigManager config;

	@Inject
	public LiveProgressReader(Client client, ConfigManager config)
	{
		this.client = client;
		this.config = config;
	}

	/** Only call on ClientThread after the login's first game tick. */
	public AccountProgress read()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null
			|| config.getRSProfileKey() == null)
		{
			return null;
		}
		String name = client.getLocalPlayer().getName();
		if (name == null || name.isBlank() || client.getAccountHash() == -1L)
		{
			return null;
		}
		RuneScapeProfileType mode = RuneScapeProfileType.getCurrent(client);
		boolean established = config.getRSProfiles().stream().anyMatch(p -> p.getKey().equals(config.getRSProfileKey())
			&& p.getAccountHash() == client.getAccountHash() && p.getType() == mode);
		if (!established)
		{
			return null;
		}
		Map<String, AccountProgress.QuestStatus> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			quests.put(quest.name(), state == QuestState.FINISHED ? AccountProgress.QuestStatus.COMPLETE
				: state == QuestState.IN_PROGRESS ? AccountProgress.QuestStatus.IN_PROGRESS
					: AccountProgress.QuestStatus.INCOMPLETE);
		}
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			if (level > 0)
			{
				levels.put(skill.name(), level);
			}
		}
		long now = System.currentTimeMillis();
		return new AccountProgress("live:" + config.getRSProfileKey() + ":" + mode.name(), name, mode.name(),
			"Live RuneLite",
			now, now, quests, levels, Collections.emptyMap(), Collections.emptySet());
	}
}

package com.questcape.progress;

import com.questcape.guide.GuideRow;
import lombok.Value;
import net.runelite.api.Experience;

@Value
public class Completion
{
	public enum State
	{
		COMPLETE, INCOMPLETE, IN_PROGRESS, UNKNOWN, INFORMATION
	}

	State state;
	boolean manual;

	public String label()
	{
		String label;
		switch (state)
		{
		case COMPLETE:
			label = "✓ Complete";
			break;
		case IN_PROGRESS:
			label = "◐ In progress";
			break;
		case INCOMPLETE:
			label = "○ Incomplete";
			break;
		case INFORMATION:
			label = "Information";
			break;
		default:
			label = manual ? "○ Not checked" : "? Unknown";
		}
		return label + (manual ? " · manual" : "");
	}

	public static Completion of(GuideRow row, AccountProgress progress)
	{
		if (!row.isActionable())
		{
			return new Completion(State.INFORMATION, false);
		}
		if (progress == null)
		{
			return new Completion(State.UNKNOWN, false);
		}
		if (row.getQuestIdentity() != null)
		{
			AccountProgress.QuestStatus state = progress.getQuests().get(row.getQuestIdentity());
			if (row.getKey().contains(":start") && state == AccountProgress.QuestStatus.IN_PROGRESS)
			{
				return new Completion(State.COMPLETE, false);
			}
			return new Completion(state == null ? State.UNKNOWN : State.valueOf(state.name()), false);
		}
		if (row.getKind() == GuideRow.Kind.TRAINING)
		{
			boolean missing = row.getTargets().isEmpty();
			for (java.util.Map.Entry<String, Integer> target : row.getTargets().entrySet())
			{
				Integer level = level(progress, target.getKey());
				if (level == null)
				{
					missing = true;
				}
				else if (level < target.getValue())
				{
					return new Completion(State.INCOMPLETE, false);
				}
			}
			return new Completion(missing ? State.UNKNOWN : State.COMPLETE, false);
		}
		Boolean fact = progress.getActivities().get(row.getKey());
		if (fact != null)
		{
			return new Completion(fact ? State.COMPLETE : State.INCOMPLETE, false);
		}
		if (row.isManual())
		{
			return new Completion(progress.getManual().contains(row.getKey()) ? State.COMPLETE : State.UNKNOWN, true);
		}
		return new Completion(State.UNKNOWN, false);
	}

	private static Integer level(AccountProgress progress, String skill)
	{
		java.util.Map<String, Integer> levels = progress.getLevels();
		if (!"COMBAT".equals(skill))
		{
			return levels.get(skill);
		}
		String[] combatSkills = {"ATTACK", "STRENGTH", "DEFENCE", "HITPOINTS", "MAGIC", "RANGED", "PRAYER"};
		for (String combatSkill : combatSkills)
		{
			Integer level = levels.get(combatSkill);
			if (level == null || level <= 0)
			{
				return null;
			}
		}
		return Experience.getCombatLevel(levels.get("ATTACK"), levels.get("STRENGTH"), levels.get("DEFENCE"),
			levels.get("HITPOINTS"), levels.get("MAGIC"), levels.get("RANGED"), levels.get("PRAYER"));
	}
}

package com.questcape.progress;

import com.questcape.guide.GuideRow;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.util.*;
import javax.inject.*;

/** Disk operations run on the serial worker; client/EDT reads and logout never wait for disk. */
@Singleton
public class ProgressService
{
	private final JsonStore store;
	private final Map<String, AccountProgress> records = new java.util.concurrent.ConcurrentHashMap<>();
	private volatile AccountProgress live;
	private long session;

	@Inject
	public ProgressService(JsonStore store)
	{
		this.store = store;
	}

	private void load(String scope) throws IOException
	{
		if (records.containsKey(scope))
		{
			return;
		}
		AccountProgress saved = store.read("progress", scope, AccountProgress.class);
		if (saved != null)
		{
			if (!scope.equals(saved.getScope()) || saved.getQuests() == null || saved.getLevels() == null
				|| saved.getManual() == null || saved.getActivities() == null || saved.getUsername() == null
				|| saved.getMode() == null)
			{
				throw new IOException("Invalid account cache; original retained");
			}
			records.put(scope, saved);
		}
	}

	public void acceptLive(AccountProgress observation) throws IOException
	{
		acceptLive(observation, token(), false);
	}

	/** A session token also prevents a disk operation finishing after logout from republishing a character. */
	public boolean acceptLive(AccountProgress observation, long expectedSession, boolean force) throws IOException
	{
		if (observation == null || expectedSession != token())
		{
			return false;
		}
		load(observation.getScope());
		AccountProgress current = live;
		boolean unchanged = current != null && current.getScope().equals(observation.getScope())
			&& current.getUsername().equals(observation.getUsername())
			&& current.getQuests().equals(observation.getQuests())
			&& current.getLevels().equals(observation.getLevels())
			&& current.getActivities().equals(observation.getActivities());
		if (!force && unchanged && observation.getRetrievedAt() - current.getRetrievedAt() < 60_000)
		{
			return expectedSession == token();
		}
		AccountProgress previous = records.get(observation.getScope());
		AccountProgress next = observation.withManual(previous == null ? Collections.emptySet() : previous.getManual());
		if (expectedSession != token())
		{
			return false;
		}
		store.write("progress", next.getScope(), next);
		records.put(next.getScope(), next);
		synchronized (this)
		{
			if (expectedSession != session)
			{
				return false;
			}
			live = next;
			return true;
		}
	}

	public synchronized void logout()
	{
		live = null;
		session++;
	}

	public synchronized long token()
	{
		return session;
	}

	public AccountProgress current()
	{
		return live;
	}

	public void toggleManual(String expectedScope, GuideRow row, boolean checked) throws IOException
	{
		long expectedSession = token();
		AccountProgress record = live;
		if (record == null || !record.getScope().equals(expectedScope) || !row.isManual())
		{
			return;
		}
		Set<String> checks = new HashSet<>(record.getManual());
		if (checked)
		{
			checks.add(row.getKey());
		}
		else
		{
			checks.remove(row.getKey());
		}
		AccountProgress changed = record.withManual(checks);
		store.write("progress", changed.getScope(), changed);
		records.put(changed.getScope(), changed);
		synchronized (this)
		{
			if (expectedSession == session && live == record)
			{
				live = changed;
			}
		}
	}
}

package com.questcape.progress;

import java.util.*;
import lombok.Value;

@Value
public class AccountProgress
{
	public enum QuestStatus
	{
		INCOMPLETE, IN_PROGRESS, COMPLETE
	}

	int schema = 1;
	String scope;
	String username;
	String mode;
	String source;
	long retrievedAt;
	Long observedAt;
	Map<String, QuestStatus> quests;
	Map<String, Integer> levels;
	Map<String, Boolean> activities;
	Set<String> manual;

	public AccountProgress(String scope, String username, String mode, String source, long retrievedAt,
		Long observedAt, Map<String, QuestStatus> quests, Map<String, Integer> levels,
		Map<String, Boolean> activities, Set<String> manual)
	{
		this.scope = scope;
		this.username = username;
		this.mode = mode;
		this.source = source;
		this.retrievedAt = retrievedAt;
		this.observedAt = observedAt;
		this.quests = Collections.unmodifiableMap(new HashMap<>(quests));
		this.levels = Collections.unmodifiableMap(new HashMap<>(levels));
		this.activities = Collections.unmodifiableMap(new HashMap<>(activities));
		this.manual = Collections.unmodifiableSet(new HashSet<>(manual));
	}

	public AccountProgress withManual(Set<String> checks)
	{
		return new AccountProgress(scope, username, mode, source, retrievedAt, observedAt, quests, levels, activities,
			checks);
	}
}

package com.questcape.progress;

import java.text.Normalizer;
import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

public final class Identities
{
	private static final Map<String, String> QUESTS = new HashMap<>();
	static
	{
		for (Quest quest : Quest.values())
		{
			QUESTS.put(normalize(quest.getName()), quest.name());
		}
		alias("Recipe for Disaster/Freeing the Mountain Dwarf", "Recipe for Disaster - Mountain Dwarf");
		alias("Recipe for Disaster/Freeing the Goblin generals", "Recipe for Disaster - Wartface & Bentnoze");
		alias("Recipe for Disaster/Freeing Pirate Pete", "Recipe for Disaster - Pirate Pete");
		alias("Recipe for Disaster/Freeing the Lumbridge Guide", "Recipe for Disaster - Lumbridge Guide");
		alias("Recipe for Disaster/Freeing Evil Dave", "Recipe for Disaster - Evil Dave");
		alias("Recipe for Disaster/Freeing Skrach Uglogwee", "Recipe for Disaster - Skrach Uglogwee");
		alias("Recipe for Disaster/Freeing Sir Amik Varze", "Recipe for Disaster - Sir Amik Varze");
		alias("Recipe for Disaster/Freeing King Awowogei", "Recipe for Disaster - King Awowogei");
		alias("Recipe for Disaster/Another Cook's Quest", "Recipe for Disaster - Another Cook's Quest");
		alias("Recipe for Disaster/Defeating the Culinaromancer", "Recipe for Disaster - Culinaromancer");
	}

	private Identities()
	{
	}

	private static void alias(String source, String target)
	{
		String id = QUESTS.get(normalize(target));
		if (id != null)
		{
			QUESTS.put(normalize(source), id);
		}
	}

	public static String normalize(String text)
	{
		return Normalizer.normalize(text == null ? "" : text, Normalizer.Form.NFKC)
			.replace('_', ' ').replace('\u00a0', ' ').replace('\u2019', '\'')
			.replace('\u2013', '-').replace('\u2014', '-').trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	public static String quest(String title)
	{
		return QUESTS.get(normalize(title));
	}

	public static String skill(String name)
	{
		String normalized = normalize(name);
		if (normalized.equals("runecrafting"))
		{
			normalized = "runecraft";
		}
		if (normalized.equals("defense"))
		{
			normalized = "defence";
		}
		for (Skill skill : Skill.values())
		{
			if (normalize(skill.getName()).equals(normalized))
			{
				return skill.name();
			}
		}
		return null;
	}
}
